const questions=raw.map((q,i)=>({id:i+1,exam:"nissho",level:q[0],topic:q[1],text:q[2],options:q[3],answer:q[4],explain:q[5]}));
questions.push(...additions.map((q,i)=>({id:"extra-"+i,exam:q[0],level:q[1],topic:q[2],text:q[3],options:q[4],answer:q[5],explain:q[6]})));
let exam="nissho";
const bank=()=>questions.filter(q=>q.exam===exam);
const examLogs=()=>state.log.filter(x=>bank().some(q=>q.id===x.id));
const unitLabel=l=>catalogs[exam].label(l);
const qLabel=q=>catalogs[q.exam].name+" "+catalogs[q.exam].label(q.level);
let state;try{state=JSON.parse(localStorage.getItem('bk-v1'))}catch{}if(!state||!Array.isArray(state.log)||!state.cards)state={log:[],cards:{}};
let level=3,queue=[],position=0,answered=false,mode='practice',sessionStart=0;const $=id=>document.getElementById(id);const day=()=>new Date().toLocaleDateString('sv-SE');const dueCards=()=>bank().filter(q=>state.cards[q.id]?.due<=Date.now());
function save(){try{localStorage.setItem('bk-v1',JSON.stringify(state))}catch{alert('記録を保存できません。ブラウザの保存設定をご確認ください。')}}
function navigate(view){document.querySelectorAll('.view').forEach(e=>e.classList.toggle('show',e.id===view));document.querySelectorAll('nav button').forEach(e=>e.classList.toggle('active',e.dataset.view===view));$('breadcrumb').textContent='MY LEARNING / '+({home:'ホーム',practice:'問題を解く',review:'間違いノート',stats:'学習の記録',profile:'つくった人',curriculum:'学習カリキュラム',studyplan:'学習プラン'}[view]);if(view==='practice'&&!queue.length)startPractice(level);renderDashboard();if(view==='review')renderReview();if(view==='stats')renderStats();if(view==='curriculum')renderCurriculum();if(view==='studyplan')renderStudyPlan();window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));
function startPractice(l){sessionStart=state.log.length;level=l;mode='practice';queue=bank().filter(q=>q.level===l).sort((a,b)=>priority(a)-priority(b));position=0;renderFilters();renderQuestion()}
function renderFilters(){$('filters').innerHTML=catalogs[exam].units.map(l=>`<button class="chip ${l===level&&mode==='practice'?'selected':''}" data-unit="${l}">${unitLabel(l)}</button>`).join('')+(mode==='review'?'<span class="chip selected">復習モード</span>':'');document.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>startPractice(catalogs[exam].units.find(l=>String(l)===b.dataset.unit)))}
function renderQuestion(){answered=false;const q=queue[position];if(!q){$('questionarea').innerHTML=`<div class="panel empty"><span class="eyebrow">WELL DONE.</span><h2 style="margin:20px">今日の積み重ねが、ひとつ形に。</h2><div class="finishcount">${state.log.length-sessionStart}問に挑戦</div><p>今回の正解 ${state.log.slice(sessionStart).filter(x=>x.correct).length}問 · 解き直して正解 ${sessionRecoveries()}問</p><p>${sessionRecoveries()>0?"前にできなかった問題が、できる問題に変わりました。":"解いた経験が、次の理解につながります。"}</p><button class="primary" id="backhome">ホームに戻る ↗</button></div>`;$('backhome').onclick=()=>{queue=[];navigate('home')};return} $('questionarea').innerHTML=`<div class="panel"><div class="questionhead"><span>${qLabel(q)} / ${q.topic}</span><span>${position+1} / ${queue.length}</span></div><div class="progressbar"><i style="width:${position/queue.length*100}%"></i></div><p class="question">${q.text}</p><div class="options">${q.options.map((o,i)=>`<button class="option" data-answer="${i}"><span class="muted">0${i+1}　</span>${o}</button>`).join('')}</div><div id="feedback" aria-live="polite"></div><div class="qactions"><span class="muted">ひとつ選んで、考え方を確認。</span><button class="textbtn" id="skip">この問題を後にする →</button></div></div>`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(+b.dataset.answer));$('skip').onclick=()=>{if(queue.length-position>1){queue.push(queue.splice(position,1)[0]);renderQuestion()}else{$('feedback').textContent='最後の問題です。解答するか、メニューから別の学習を選べます。'}}}
function answer(a){if(answered)return;answered=true;const q=queue[position],correct=a===q.answer;const prev=state.cards[q.id]||{step:0,wrong:0};const recovered=correct&&prev.last===false;const step=correct?Math.min(prev.step+1,5):0;const days=[0,1,3,7,14,30][step];state.cards[q.id]={step,wrong:prev.wrong+(correct?0:1),due:Date.now()+days*86400000,last:correct};state.log.push({id:q.id,correct,recovered,date:day(),time:Date.now()});save();document.querySelectorAll('[data-answer]').forEach(b=>{b.disabled=true;if(+b.dataset.answer===q.answer)b.classList.add('correct');else if(+b.dataset.answer===a)b.classList.add('wrong')});$('feedback').innerHTML=`<div class="result"><b>${correct?'○ 正解。理解がひとつ、前へ。':'↻ ここが、理解の入り口。'}</b>${q.explain}${recovered?'<p><strong>できなかった一問が、できた一問に。</strong></p>':''}<p class="muted">次の復習：${correct?days+'日後':'今日（間違いノートから再挑戦）'}</p><button class="primary" id="next">${position+1===queue.length?'学習を終える':'次の問題へ'} <span>→</span></button></div>`;$('skip').hidden=true;$('next').onclick=()=>{position++;renderQuestion()};renderDashboard()}
function renderDashboard(){renderExamSwitch();renderLearningStatus();const n=examLogs().length,c=examLogs().filter(x=>x.correct).length,d=dueCards().length;$('total').innerHTML=n+'<span>問</span>';$('accuracy').innerHTML=(n?Math.round(c/n*100):'—')+'<span>%</span>';$('due').innerHTML=d+'<span>問</span>';if(d){$('herotitle').textContent=`今日は、${d}問をもう一度。`;$('herotext').innerHTML='間違えたところに、伸びしろがある。<br>少し前の「わからない」を、今日の「わかる」に。'}else{$('herotitle').textContent=n?'今日も、ひとつ先の理解へ。':'まずは、ひとつ解いてみよう。';$('herotext').innerHTML='あなたの「わからない」を見つけるところから。<br>1問ずつ、確かな理解を積み重ねよう。'}$('courses').innerHTML=catalogs[exam].units.map(l=>`<button class="course" data-course="${l}"><span class="level" style="font-size:12px">${exam==='uscpa'?l:exam==='nissho'?l+'級':'全経'}</span><span class="coursebody"><b>${unitLabel(l)}</b><p>${bank().filter(q=>q.level===l).length}問 · ${exam==='uscpa'?'英語問題 / 日本語解説':'日本語問題 / 解説付き'}</p></span><span class="arrow">↗</span></button>`).join('');document.querySelectorAll('[data-course]').forEach(b=>b.onclick=()=>{startPractice(catalogs[exam].units.find(l=>String(l)===b.dataset.course));navigate('practice')});$('week').innerHTML=Array.from({length:7},(_,i)=>{const t=new Date();t.setDate(t.getDate()-6+i);const date=t.toLocaleDateString('sv-SE');return `<i title="${date}" class="${examLogs().some(x=>x.date===date)?'done':''}"></i>`}).join('')}
function beginReview(){sessionStart=state.log.length;queue=dueCards();if(!queue.length){navigate('review');return}mode='review';position=0;renderFilters();renderQuestion();navigate('practice')}
$('start').onclick=()=>{if(dueCards().length)beginReview();else{startPractice(level);navigate('practice')}};$('reviewstart').onclick=beginReview;
function renderReview(){const cards=bank().filter(q=>state.cards[q.id]?.wrong>0).sort((a,b)=>state.cards[a.id].due-state.cards[b.id].due);$('reviewstart').disabled=dueCards().length===0;$('reviewlist').innerHTML=cards.length?cards.map(q=>{const c=state.cards[q.id];return `<div class="reviewrow"><div><span class="muted">${qLabel(q)} / 誤答 ${c.wrong}回</span><p>${q.topic}</p><span class="muted">${c.due<=Date.now()?'今日の復習対象':new Date(c.due).toLocaleDateString('ja-JP')+' に復習'}</span></div><button class="chip" data-retry="${q.id}">もう一度 ↗</button></div>`}).join(''):'<div class="panel empty">まだ間違いは記録されていません。<br>問題に挑戦すると、ここに苦手な論点が集まります。</div>';document.querySelectorAll('[data-retry]').forEach(b=>b.onclick=()=>{sessionStart=state.log.length;queue=[questions.find(q=>String(q.id)===b.dataset.retry)];mode='review';position=0;renderFilters();renderQuestion();navigate('practice')})}
function renderStats(){$('statbody').innerHTML=catalogs[exam].units.map(l=>{const ids=bank().filter(q=>q.level===l).map(q=>q.id),logs=examLogs().filter(x=>ids.includes(x.id)),rate=logs.length?Math.round(logs.filter(x=>x.correct).length/logs.length*100):0;return `<div class="panel"><div class="sectiontitle"><h2>${catalogs[exam].name} ${unitLabel(l)}</h2><span>${logs.length} 解答 / 正答率 ${logs.length?rate+'%':'—'}</span></div><p class="intro">取り組んだ問題 ${new Set(logs.map(x=>x.id)).size} / ${ids.length}問</p><div class="progressbar"><i style="width:${rate}%"></i></div></div>`}).join('')+'<p class="intro">選択中の試験の全解答に対する正解の割合です。</p>'+topicMap()}
$('export').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='book-keeping-'+day()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};$('about').onclick=()=>$('info').showModal();$('date').textContent=new Date().toLocaleDateString('ja-JP',{month:'2-digit',day:'2-digit',weekday:'short'});renderDashboard();

function priority(q){const c=state.cards[q.id];if(c?.due<=Date.now())return 0;if(!c)return 1;return 2+c.step}
function sessionRecoveries(){return state.log.slice(sessionStart).filter(x=>x.recovered).length}
function stage(q){const c=state.cards[q.id];if(!c)return 0;if(!c.last)return 1;if(c.step<2)return 2;return 3}
function advice(){const logs=examLogs(),recent=logs.slice(-5),units=catalogs[exam].units,latestLevel=logs.length?questions.find(q=>q.id===logs.at(-1).id).level:units[0],all=bank().filter(q=>q.level===latestLevel).every(q=>state.cards[q.id]?.last),next=units[units.indexOf(latestLevel)+1];if(dueCards().length)return {label:'解き直しで、ひとつ前へ。',text:'選択中の試験に、復習のタイミングを迎えた問題があります。',action:'復習に取り組む',level:latestLevel,review:true};if(recent.length>=3&&recent.filter(x=>!x.correct).length>=2)return {label:'ひとつずつ、理解を確かめよう。',text:'解説を読んでから、同じコースをもう一周してみましょう。',action:unitLabel(latestLevel)+'を練習',level:latestLevel};if(all&&next!==undefined)return {label:'次の挑戦を、少しだけ。',text:'このコースの収録問題はすべて直近の解答で正解。別のコースも体験できます。'+(exam==='uscpa'?'選択科目は難易度順ではありません。興味に合わせて選べます。':''),action:unitLabel(next)+'を体験',level:next};return {label:logs.length?'いいリズムで、積み重ねよう。':'まずは、小さな目標から。',text:'今日の目安は5問。途中でやめても、積み重ねは残ります。速さは自分のペースで。',action:unitLabel(latestLevel)+'を練習',level:latestLevel}}
function renderLearningStatus(){const host=$('learningstatus');if(!host)return;const today=examLogs().filter(x=>x.date===day()),unique=new Set(examLogs().map(x=>x.id)).size,recovered=examLogs().filter(x=>x.recovered).length,counts=[0,1,2,3].map(i=>bank().filter(q=>stage(q)===i).length),a=advice();host.innerHTML=`<div class="statusbox"><div class="sectiontitle"><h2>いまの学びのステータス</h2><span class="growthpill">${a.label}</span></div><div class="statusgrid"><div><span class="muted">今日の積み重ね</span><strong>${today.length}<small class="muted"> / 目安5問</small></strong></div><div><span class="muted">出会った問題</span><strong>${unique}<small class="muted"> / ${bank().length}問</small></strong></div><div><span class="muted">解き直して正解</span><strong>${recovered}<small class="muted"> 回</small></strong></div></div><div class="progressbar" role="progressbar" aria-label="今日の5問目標" aria-valuemin="0" aria-valuemax="5" aria-valuenow="${Math.min(today.length,5)}"><i style="width:${Math.min(today.length/5*100,100)}%"></i></div><p>${today.length>=5?'今日の目安、達成。ここで一区切りにしても、もう少し挑戦しても。':'あと'+(5-today.length)+'問で、今日の目安に到達。'}</p><div class="stages"><span>未挑戦 ${counts[0]}</span><span>見直し中 ${counts[1]}</span><span>理解の芽 ${counts[2]}</span><span>定着へ ${counts[3]}</span></div><p>${a.text}</p><div class="statusactions"><button class="primary" id="recommended">${a.action} ↗</button><button class="textbtn" id="viewgrowth">論点ごとの成長を見る →</button></div></div>`;$('recommended').onclick=()=>{if(a.review)beginReview();else{startPractice(a.level);navigate('practice')}};$('viewgrowth').onclick=()=>navigate('stats')}
function topicMap(){return '<div class="panel"><h2>演習ごとの記録</h2><p class="intro">未解答 → 要復習 → 直近正解 → 連続正解。<br>「連続正解」は収録された同じ問題での結果です。初見の類題や試験範囲全体の習熟度ではありません。</p>'+bank().map(q=>`<div class="topicstatus"><span>${qLabel(q)} / ${q.topic}</span><span>${['未解答','要復習','直近正解','連続正解'][stage(q)]} · 連続正解 ${state.cards[q.id]?.step===5?'5回以上':(state.cards[q.id]?.step||0)+'回'}</span></div>`).join('')+'</div>'}
renderLearningStatus();

function renderExamSwitch(){const host=$('examswitch');if(!host)return;host.innerHTML=`<label for="examselect" class="eyebrow">LEARNING TRACK / 学ぶ試験</label><select id="examselect" style="padding:12px;margin:12px 0;width:100%;background:var(--paper);border:1px solid var(--ink);border-radius:3px">${Object.entries(catalogs).map(([id,c])=>`<option value="${id}" ${id===exam?'selected':''}>${c.name}</option>`).join('')}</select><p style="font-size:11px;line-height:1.9;margin:0">${catalogs[exam].standard} · ${bank().length}問<br>${catalogs[exam].intro}</p>`;$('examselect').onchange=e=>{exam=e.target.value;level=state.targets?.[exam]??catalogs[exam].units[0];queue=[];saveTrack();renderFilters();$('questionarea').innerHTML='';const visible=document.querySelector('.view.show')?.id||'home';navigate(visible);};}
function saveTrack(){try{localStorage.setItem('bk-track',exam)}catch{}}
try{const preferred=localStorage.getItem('bk-track');if(catalogs[preferred]){exam=preferred;level=catalogs[exam].units[0]}}catch{}
renderDashboard();

$('creator-learn').onclick=()=>navigate('curriculum');
